      },
      {
        "concept": "Political Primacy",
        "description": "Counterinsurgency is fundamentally a political struggle. Military actions must support political goals. Legitimacy of the host government and countering insurgent narratives are crucial."
      },
      {
        "concept": "Intelligence and Information Operations",
        "description": "Effective COIN relies on precise intelligence to separate insurgents from civilians. Information operations are used to counter propaganda and win the narrative battle, now expanded into the cyber domain."
      },
      {
        "concept": "Legal and Ethical Frameworks",
        "description": "Operations must adhere to international humanitarian law (e.g., distinction, proportionality). Ethical dilemmas arise from close interaction with civilians and the use of targeted killings or drone strikes."
      },
      {
        "concept": "Modern Challenges",
