{
  "teaching_material": {
    "topic": "Basic Concepts of Force and Motion",
    "teaching_objectives": {
      "cognitive": [
        "Define force and describe its effects on objects (change in motion, direction, or shape).",
        "Distinguish between contact and non-contact forces with examples.",
        "Explain the relationship between force and motion using Newton's First Law (inertia).",
        "Understand that balanced forces result in no change in motion, while unbalanced forces cause acceleration."
      ],
      "skill": [
        "Predict the motion of an object based on the net force acting on it.",
        "Draw and interpret simple free-body diagrams.",
        "Conduct simple experiments to observe the effects of forces."
      ],
      "affective": [
        "Develop curiosity about how forces govern everyday motion.",
        "Appreciate the role of friction in daily life (both helpful and problematic)."
      ]
    },
    "key_points": [
      "Force is a push or pull; it is a vector quantity (has magnitude and direction).",
      "Net force (resultant force) determines whether an object’s motion changes.",
      "Balanced forces → object at rest stays at rest, or moves at constant velocity.",
      "Unbalanced forces → change in speed and/or direction (acceleration).",
      "Inertia: tendency of an object to resist changes in its state of motion; depends on mass.",
      "Friction is a common contact force that opposes motion."
    ],
    "difficulties": [
      "Misconception: 'A constant force is needed to keep an object moving.' (Newton’s First Law contradicts this.)",
      "Confusing velocity and acceleration; students may think force causes velocity, not acceleration.",
      "Overlooking direction when adding forces – treating forces as scalars.",
      "Understanding that friction can act even when an object is not moving (static friction).",
      "Applying the concept of inertia to real-world scenarios (e.g., passengers lurching forward in a braking car)."
    ],
    "classroom_activity_design": {
      "warm_up": {
        "duration": "5 min",
        "description": "Show a short video or animation of objects in motion (car accelerating, ball rolling to a stop, magnet attracting a paperclip). Ask: 'What made the object move or stop? List all the pushes and pulls you see.'",
        "purpose": "Activate prior knowledge and elicit ideas about forces."
      },
      "introduction": {
        "duration": "10 min",
        "description": "Define force, show examples of contact (push, pull, friction) and non-contact (gravity, magnetic) forces. Use a simple diagram to illustrate vector arrows. Introduce the notion of net force with a tug-of-war analogy.",
        "materials": "Whiteboard/projector, force arrows cutouts or digital slides."
      },
      "main_activities": [
        {
          "name": "Station 1: Tug-of-War (Net Force)",
          "duration": "15 min",
          "description": "Groups of 4 students pull on a rope with spring scales attached. They vary forces to create balanced and unbalanced situations. Observe when the rope moves or stays still. Record readings and direction.",
          "materials": "Rope, spring scales (2 per side), markers to indicate movement.",
          "discussion_points": "What happens when both sides pull equally? What causes the rope to accelerate?"
