        {
          "name": "Station 3: Friction Ramp",
          "duration": "15 min",
          "description": "Roll a toy car on different surfaces (carpet, smooth tile, sandpaper). Measure distance traveled with same initial push. Relate to friction force opposing motion.",
          "materials": "Toy cars, ramp, various surface materials, tape measure.",
          "discussion_points": "On which surface did the car stop soonest? Why?"
        }
      ],
      "group_discussion_and_consolidation": {
        "duration": "10 min",
        "description": "Groups share findings. Teacher guides students to summarize: balanced forces → no change; unbalanced forces → change; friction always opposes motion; inertia resists changes. Address misconceptions explicitly.",
        "materials": "Whiteboard for notes, sticky notes for student ideas."
      },
      "assessment_activity": {
        "duration": "5 min",
        "description": "Exit ticket: Provide three short scenarios (e.g., a hockey puck sliding on ice, a book on a table, a magnet pulling a nail). Students identify forces and predict motion. Collect to check understanding.",
        "materials": "Printed slips or digital form."
      }
    },
    "materials_needed": [
      "Projector and screen",
      "Spring scales (at least 8)",
      "Rope (3-4 meters)",
      "Coins and paper",
      "Toy cars and ramps",
      "Various surface samples (sandpaper, cloth, tile)",
      "Tape measures",
      "Whiteboard and markers",
      "Exit ticket slips"
    ],
    "assessment_methods": {
      "formative": [
        "Observations during station activities and discussions.",
        "Student responses in exit tickets.",
        "Group presentations."
      ],
      "summative": "Short quiz at the end of the unit covering definitions, net force, inertia, and real-life applications."
    },
    "extensions": {
      "homework": "Find three examples at home where forces cause a change in motion. Describe the forces involved and whether they are balanced/unbalanced.",
      "enrichment": "Research how astronauts experience inertia in space. Create a short presentation or video."
    },
    "safety_notes": "Ensure tug-of-war is done gently to avoid injury. Supervise use of spring scales to prevent overstretching."
  }
